 * Parses the line-oriented election format described in the task prompt:
 * a single `candidates` declaration followed by any number of `ballot`
 * records, comments (`#`) and blank lines ignored.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** Thrown for any parse failure; `line` is null for the "no candidates" case. */
export class CliError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * @param {string} text raw standard input
 * @returns {{ candidates: string[], ballots: { count: bigint, prefs: string[] }[] }}
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidatesDeclared = false
  const candidateSet = new Set()
  const candidateOrder = []
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new CliError(lineNo, 'candidates must be declared once, before any ballot')
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new CliError(lineNo, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new CliError(lineNo, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          throw new CliError(lineNo, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
        candidateOrder.push(name)
      }
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new CliError(lineNo, 'candidates must be declared once, before any ballot')
      }
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        throw new CliError(lineNo, 'expected ballot <count> <candidate>...')
      }
      const [countStr, ...prefs] = rest
      if (!COUNT_RE.test(countStr)) {
        throw new CliError(lineNo, 'count must be a positive integer')
      }
      const seen = new Set()
      for (const name of prefs) {
        if (!candidateSet.has(name)) {
          throw new CliError(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new CliError(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count: BigInt(countStr), prefs })
    } else {
      throw new CliError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (!candidatesDeclared) {
    throw new CliError(null, 'no candidates')
  }

  return { candidates: candidateOrder, ballots }
}
"}

