{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-HinbSf/src/election.js","content":"/**
 * Runs an instant-runoff count over a set of candidates and ballots,
 * eliminating one candidate per round using the tie-break rule described
 * in the task prompt: fewest votes this round, then fewest across the
 * rounds already counted from the first round onwards, then last by
 * code point.
 */

/**
 * @param {string[]} candidates
 * @param {{ count: bigint, prefs: string[] }[]} ballots
 * @returns {{ rounds: { votes: Map<string, bigint>, exhausted: bigint, eliminated: string|null }[], winner: string|null }}
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const chosen = ballot.prefs.find((name) => continuing.has(name))
      if (chosen !== undefined) {
        votes.set(chosen, votes.get(chosen) + ballot.count)
      } else {
        exhausted += ballot.count
      }
    }

    let activeTotal = 0n
    for (const count of votes.values()) activeTotal += count
    history.push(votes)

    if (activeTotal === 0n) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = null
      break
    }

    const majority = [...votes.entries()].find(([, count]) => count * 2n > activeTotal)
    if (majority) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = majority[0]
      break
    }

    let minVal = null
    for (const count of votes.values()) {
      if (minVal === null || count < minVal) minVal = count
    }
    const tied = [...votes.keys()].filter((name) => votes.get(name) === minVal)
    const eliminated = pickEliminated(tied, history)
    rounds.push({ votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/** Picks which of the tied candidates to eliminate, per the tie-break rule. */
function pickEliminated(tied, history) {
  let candidates = tied
  let r = 0
  while (candidates.length > 1 && r < history.length) {
    const votesMap = history[r]
    let minVal = null
    for (const name of candidates) {
      const count = votesMap.get(name)
      if (minVal === null || count < minVal) minVal = count
    }
    const narrowed = candidates.filter((name) => votesMap.get(name) === minVal)
    if (narrowed.length < candidates.length) {
      candidates = narrowed
      r = 0
    } else {
      r++
    }
  }
  if (candidates.length === 1) return candidates[0]
  return [...candidates].sort().at(-1)
}
"}

